INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('019f9ebf-c0d6-7cce-92bf-0d30400cfc26'::uuid, '019f9df7-a2a2-7865-ab8c-df9bc214c173'::uuid, 'A function is given by s = (r - 3q) / q^2. Evaluate s when q = -3 and r = 5.', '14/9', 'Substitute q = -3 and r = 5 into s = (r - 3q) / q^2. Then s = (5 - 3(-3)) / (-3)^2 = 14/9.', 'Easy', '{"tags":"functions,substitution,algebra","subtopic":"substitution","question_type":"open-ended","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-07-26T14:06:34.710Z'::timestamptz, '2026-07-26T14:06:34.710Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b88-7aec-a320-05e9aeda492f'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'The universal set contains the integers from 1 to 15. Set A contains the perfect squares and set B contains the prime numbers. Find n(A ∪ B).', '9', 'A = {1, 4, 9}. B = {2, 3, 5, 7, 11, 13}. There is no overlap, so n(A ∪ B) = 3 + 6 = 9.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.424Z'::timestamptz, '2026-08-15T07:36:12.424Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8b9c-7a18-81ec-2dd7d0fc76a3'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'The universal set contains the integers from 1 to 15. Set B contains the prime numbers. List the elements of B''.', '{1, 4, 6, 8, 9, 10, 12, 14, 15}', 'The primes from 1 to 15 are 2, 3, 5, 7, 11 and 13. The complement B'' contains all other integers in the universal set.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.444Z'::timestamptz, '2026-08-15T07:36:12.444Z'::timestamptz) ON CONFLICT (id) DO NOTHING;